<?php
require __DIR__.'/../includes/bootstrap.php';require_can('appointment.write');v2_require();$grace=max(0,workflow_setting('overdue_grace_minutes',60));
$rows=q_all("SELECT a.*,p.full_name,d.full_name AS doctor_name FROM appointment a JOIN patient p ON p.patient_id=a.patient_id JOIN doctor d ON d.doctor_id=a.doctor_id WHERE a.status IN ('SCHEDULED','CONFIRMED') AND a.start_at<DATE_SUB(NOW(),INTERVAL $grace MINUTE) AND NOT EXISTS(SELECT 1 FROM clinical_visit v WHERE v.appointment_id=a.appointment_id) AND NOT EXISTS(SELECT 1 FROM arrival_queue_entry q WHERE q.appointment_id=a.appointment_id AND q.status='WAITING') ORDER BY a.start_at");
page_start('Bookings needing review',['nav'=>'appointments','subtitle'=>count($rows).' bookings without a check-in or visit. Both scheduled and confirmed bookings are included.']);
?><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Start time</th><th>Patient</th><th>Doctor</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= e(fmt_dt($r['start_at'])) ?></td><td><?= e($r['full_name']) ?></td><td><?= e($r['doctor_name']) ?></td><td><?= status_badge($r['status']) ?></td><td><a href="<?= e(url('appointments/view.php?id='.$r['appointment_id'])) ?>">Review booking →</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><p class="muted">All caught up. No overdue bookings need review.</p><?php endif;?></section><?php page_end();
